import type { Authentication, Bundle, ZObject } from "zapier-platform-core";

import { getDocumensoClient, handleDocumensoError } from "./lib/client.js";

const test = async (z: ZObject, bundle: Bundle) => {
  try {
    const client = getDocumensoClient(bundle);

    const response = await client.envelope.envelopeFind({
      page: 1,
      perPage: 1,
      type: "DOCUMENT",
    });

    return {
      baseUrl: bundle.authData.baseUrl || "https://app.documenso.com/api/v2",
      status: "connected",
      totalDocuments: response.totalPages,
    };
  } catch (error) {
    handleDocumensoError(z, error);
  }
};

