import { defineCreate } from "zapier-platform-core";
import { getDocumensoClient, handleDocumensoError } from "../../lib/client.js";

export default defineCreate({
  key: "recipient_create",
  noun: "Recipient",

  display: {
    label: "Create Recipient",
    description: "Adds recipients to an existing document or template.",
  },

  operation: {
    inputFields: [
      {
        key: "documentId",
        label: "Document/Template ID",
        type: "string",
        required: true,
        helpText: "The ID of the document or template to add recipients to.",
      },
      {
        key: "recipients",
        label: "Recipients",
        children: [
          {
            key: "email",
            label: "Email",
            type: "string",
            required: true,
          },
          {
            key: "name",
            label: "Name",
            type: "string",
            required: true,
          },
          {
            key: "role",
            label: "Role",
            type: "string",
            required: true,
            choices: ["SIGNER", "APPROVER", "CC", "VIEWER", "ASSISTANT"],
            default: "SIGNER",
          },
          {
            key: "signingOrder",
            label: "Signing Order",
            type: "integer",
            required: false,
            default: "0",
            helpText: "The order in which this recipient should sign.",
          },
        ],
        list: true,
        required: true,
        helpText: "The recipients to add.",
      },
    ],

    perform: async (z, bundle) => {
      try {
        const client = getDocumensoClient(bundle);

        const recipients = (bundle.inputData.recipients || []).map((r) => ({
          email: r.email as "" | string,
          name: r.name,
          role: (r.role || "SIGNER") as EnvelopeRecipientCreateManyRoleRequest,
          signingOrder: r.signingOrder ? Number(r.signingOrder) : undefined,
        }));

        const response = await client.envelopes.recipients.createMany({
          envelopeId: bundle.inputData.documentId,
          data: recipients,
        });

        return response;
      } catch (error) {
        handleDocumensoError(z, error);
      }
    },

    sample: {
      data: [
        {
          envelopeId: "clx1abc2def3ghi4jkl5mno6p",
