import { Documenso } from "@documenso/sdk-typescript";
import type { Bundle, ZObject } from "zapier-platform-core";

const DEFAULT_BASE_URL = "https://app.documenso.com/api/v2";

/**
 * Downloads a file from a URL (typically a Zapier hydrated file URL) and returns
 * it as a Uint8Array with the resolved filename.
 */
export async function downloadFile(
  z: ZObject,
  fileUrl: string,
): Promise<{ content: Uint8Array; fileName: string }> {
  const response = await z.request({
    url: fileUrl,
    raw: true,
  });


  const buffer = await response.buffer();
  const content = new Uint8Array(buffer);

  // Try to extract filename from Content-Disposition header, URL path, or fallback
  let fileName = "document.pdf";

  const contentDisposition =
    response.headers?.get?.("content-disposition") || "";

    const filenameMatch = contentDisposition.match(
    /filename\*?=(?:UTF-8''|")?([^";]+)"?/i,
  );

  if (filenameMatch?.[1]) {
    fileName = decodeURIComponent(filenameMatch[1].trim());
  } else {
    try {
      const urlPath = new URL(fileUrl).pathname;

      const urlFilename = urlPath.split("/").pop();

      if (urlFilename && urlFilename.includes(".")) {
        fileName = decodeURIComponent(urlFilename);
      }
    } catch {
      // Keep default filename
    }
  }

  return { content, fileName };
}

/**
 * Downloads multiple files from Zapier file URLs in parallel.
 * Accepts either a single URL string or an array of URL strings.
 */
export async function downloadFiles(
  z: ZObject,
  fileUrls: string | string[],
): Promise<Array<{ content: Uint8Array; fileName: string }>> {
  const urls = Array.isArray(fileUrls) ? fileUrls : [fileUrls];

  return Promise.all(urls.map((url) => downloadFile(z, url)));
}

export function getDocumensoClient(bundle: Bundle): Documenso {
  const apiKey = [REDACTED] as string;
  const baseUrl = (bundle.authData.baseUrl as string) || DEFAULT_BASE_URL;

  if (!apiKey) {
    throw new Error("API key is required");
  }

  return new Documenso({
    apiKey,
    serverURL: baseUrl,
  });
}

export function handleDocumensoError(z: ZObject, error: unknown): never {
  if (error instanceof Error) {
    const sdkError = error as any;

    const message =
      sdkError.data$?.message || sdkError.message || "Unknown error";

    const details: string[] = [];

    if (sdkError.statusCode) {
      details.push(`Status: ${sdkError.statusCode}`);
    }

    if (sdkError.data$?.issues && Array.isArray(sdkError.data$.issues)) {
      const issueMessages = sdkError.data$.issues
        .map((issue: any) => issue.message)
        .filter(Boolean);

      if (issueMessages.length > 0) {
        details.push(issueMessages.join(", "));
      }
    }

    const fullMessage = details.length
      ? `${message} | ${details.join(" | ")}`
      : message;

    throw new z.errors.Error(
      fullMessage,
      "DocumensoError",
      sdkError.statusCode,
    );
  }

  throw new z.errors.Error("An unknown error occurred", "DocumensoError", 500);
}

